30	export async function recordConversationOffered(
31	  server: CodeAssistServer,
32	  traceId: string | undefined,
33	  response: GenerateContentResponse,
34	  streamingLatency: StreamingLatency,
35	  abortSignal: AbortSignal | undefined,
36	): Promise<void> {
37	  try {
38	    if (traceId) {
39	      const offered = createConversationOffered(
40	        response,
41	        traceId,
42	        abortSignal,
43	        streamingLatency,
44	      );
45	      if (offered) {
46	        await server.recordConversationOffered(offered);
47	      }
48	    }
49	  } catch (error: unknown) {
50	    debugLogger.warn(
51	      `Error recording tool call interactions: ${getErrorMessage(error)}`,
52	    );
53	  }
54	}
